import itertools


def flatten_lists(lists):
    return list(itertools.chain.from_iterable(lists))


def merge_dicts(*dicts):
    return dict(itertools.chain(*(d.items() for d in dicts)))


def interleave(a, b):
    result = []
    for x, y in zip(a, b):
        result.append(x)
        result.append(y)
    return result
